using FluNET.Language;using FluNET.Language.Resources;using FluNET.Prompt.Surface;namespace FluNET.Compilation.Inference;public sealed class InferenceEngine(ResourceClassifier resources,FormatInference formats,VariableNameInference names){public InferenceEngine():this(new ResourceClassifier(),new FormatInference(),new VariableNameInference()){}public ResourceDescriptor InferResource(SurfaceValueSyntax v,LanguageSnapshot l,InferenceTrace? t=null){ResourceReference r=resources.Classify(v);ResourceFormat f=formats.Infer(r);TypeSymbol type=InferredType(l.Types,r,f);string name=names.Infer(r);t?.Add(new(InferenceKind.Resource,v.Text,r is FileResourceReference file&&file.IsPattern?"LocalFilePattern":r.Kind.ToString(),"resource-prefix-or-uri-shape",v.Span));t?.Add(new(InferenceKind.Format,v.Text,f.ToString(),"resource-extension-or-scheme",v.Span));t?.Add(new(InferenceKind.Type,v.Text,type.Name,"format-to-language-type",v.Span));t?.Add(new(InferenceKind.VariableName,v.Text,name,"resource-name",v.Span));return new(r,f,type,name);}private static TypeSymbol InferredType(LanguageTypeSystem t,ResourceReference r,ResourceFormat f){TypeSymbol type=f switch{ResourceFormat.Json=>t.Json,ResourceFormat.Csv=>t.List(t.Json),ResourceFormat.Xml=>t.Json,ResourceFormat.Text=>t.Text,ResourceFormat.Binary=>t.Get<BinaryValue>(),ResourceFormat.Image=>t.Get<ImageValue>(),ResourceFormat.Unknown when r is SqlResourceReference=>t.List(t.Json),ResourceFormat.Unknown when r is EnvironmentResourceReference or SecretResourceReference=>t.Text,_=>t.Object};return r is FileResourceReference file&&file.IsPattern&&f!=ResourceFormat.Csv?t.List(type):type;}}
